import{_ as a,o as n,a as p,b as l}from"./app.DKoEZOcr.js";const c="/ascendc.github.io/pr/5487/assets/fixpipe_buffer_02.8nyTB8MX.png",h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（ISASI）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI"},{"text":"矩阵计算的搬入","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/cube_compute_load"},{"text":"DataCopy（L1ToFixpipe-Buffer数据搬运）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/DataCopy_L1ToFixpipe"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/DataCopy_L1ToFixpipe.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/DataCopy_L1ToFixpipe.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),t={name:"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/DataCopy_L1ToFixpipe.md"};function e(i,s,o,d,r,u){return n(),p("div",null,[...s[0]||(s[0]=[l('<div><article class="markdown-body"><h1>DataCopy（L1ToFixpipe-Buffer数据搬运）<a id="ZH-CN_TOPIC_0000002569070951"></a></h1><h2 id="产品支持情况">产品支持情况<a id="zh-cn_topic_0000002538001510_section18204144912492"></a><a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><div data-filter="x90"><ul><li>Kirin X90：不支持</li></ul></div><div data-filter="9030"><ul><li>Kirin 9030：不支持</li></ul></div><h2 id="功能说明">功能说明<a id="zh-cn_topic_0000002538001510_section618mcpsimp"></a><a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/kernel_operator_data_copy_intf.h&quot;</code>。</p><p>DataCopy数据搬运支持将随路量化参数从L1 Buffer移动到Fixpipe Buffer。Fixpipe Buffer包含两种参数：pre_stage的量化参数，这些参数各自独立存储，并拥有独立的地址空间。量化参数和ReLU参数通过dst地址的高16位（dst[31:16]）进行区分，具体如下：</p><p><strong>图1</strong> Fixpipe Buffer图示</p><p><img src="'+c+`" alt></p><h2 id="函数原型">函数原型<a id="section_function_prototype"></a><a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 连续搬运场景</span>
<span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">DataCopy</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">count</span><span class="p">)</span>

<span class="c1">// 连续或非连续搬运场景（高维切分）</span>
<span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">DataCopy</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">DataCopyParams</span><span class="o">&amp;</span><span class="w"> </span><span class="n">repeatParams</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<a id="section_param_desc"></a><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>操作数的数据类型。对于pre_stage的量化参数的搬运需要设置为uint64_t。支持的数据类型请参考<a href="#section_data_type">数据类型</a>。</td></tr></tbody></table><p><strong>表2</strong> 参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数，类型为LocalTensor。存储位置为Fixpipe Buffer，目的地址需要128字节对齐。</td></tr><tr><td>src</td><td>输入</td><td>源操作数，类型为LocalTensor，存储位置为L1 Buffer，源地址需要32字节对齐。</td></tr><tr><td>repeatParams</td><td>输入</td><td>搬运参数，DataCopyParams类型。通过该参数可配置搬运的数据块大小、个数、间隔等信息，同时支持非连续和连续搬运。<br>上述结构体参数定义请参考<code>\${INSTALL_DIR}/asc/include/basic_api/kernel_struct_data_copy.h</code>，<code>\${INSTALL_DIR}</code>请替换为CANN软件安装后文件存储路径。</td></tr><tr><td>count</td><td>输入</td><td>参与搬运的元素个数。<br><strong>注：count * sizeof(T)需要32字节对齐，若未对齐，搬运量会向下取整到32字节对齐。</strong></td></tr></tbody></table><p><strong>表3</strong> DataCopyParams结构体参数定义</p><table><thead><tr><th>参数名</th><th>含义</th></tr></thead><tbody><tr><td>blockCount</td><td>待搬运的连续传输数据块个数。uint16_t类型，取值范围：blockCount∈[1, 4095]。<br><strong>注：blockCount = 0表示不执行搬运，该接口将被视为NOP（空操作）。</strong></td></tr><tr><td>blockLen</td><td>待搬运的每个连续传输数据块长度，dst位于Fixpipe Buffer时，单位为128字节。uint16_t类型，取值范围：blockLen∈[1, 65535]。<br><strong>注：blockLen = 0表示不执行搬运，该接口将被视为NOP（空操作）。</strong></td></tr><tr><td>srcGap</td><td>在L1 Buffer -&gt; Fixpipe Buffer场景中，srcGap特指源操作数相邻连续数据块的间隔（前面一个数据块的头与后面数据块的头的间隔），单位为DataBlock（32字节）。uint16_t类型，srcGap∈[0, 2^16-1]。<br>  • blockCount = 1时，srcGap无意义，设置为0即可。<br>  • blockCount ≠ 1时，当srcGap=0时，表示重复搬出源操作数的第一个数据块。</td></tr><tr><td>dstGap</td><td>在L1 Buffer -&gt; Fixpipe Buffer场景中，dstGap特指目的操作数相邻连续数据块的间隔（前面一个数据块的头与后面数据块的头的间隔），单位为DataBlock（128字节）。uint16_t类型，dstGap不要超出该数据类型的取值范围，dstGap∈[1, 2^16-1]。<br>  • blockCount = 1时，dstGap无意义，设置为0即可。<br>  • blockCount ≠ 1时，当dstGap=0时，表示目的矩阵中搬入的每个数据块都会覆盖第一个数据块。</td></tr></tbody></table><h2 id="数据类型">数据类型<a id="section_data_type"></a><a class="header-anchor" href="#数据类型">​</a></h2><p>src数据类型支持uint64_t，dst数据类型支持uint64_t。</p><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<a id="section_constraint"></a><a class="header-anchor" href="#约束说明">​</a></h2><div data-filter="950"><ul><li>针对Ascend 950PR/Ascend 950DT，blockLen参数单位为64B。</li></ul></div><ul><li>dst物理内存为Fixpipe Buffer起始地址要求128字节对齐，src物理内存为L1 Buffer，起始地址要求32字节对齐。</li><li>blockCount取值范围：blockCount∈[1, 4095]，设置为0表示不执行，此指令将被视为NOP并报告警告。</li><li>srcGap∈[0, 2^16-1]，dstGap∈[1, 2^16-1]。</li><li>如果读写地址大于对应的mem_block，地址将被绕行并引发警告。</li><li>如果Fixpipe Buffer中的目标dst地址溢出，将引发异常。</li></ul><h2 id="调用示例">调用示例<a id="section_call_example"></a><a class="header-anchor" href="#调用示例">​</a></h2><p>L1 Buffer(C1)-&gt;Fixpipe Buffer(C2PIPE2GM)，搬运Vector量化参数。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// c1Addr = 0、fbAddr = 0、N = 256、n = 256；burstLen = CeilAlign(256 * sizeof(uint64_t), 128) / 128 = 16，dataCopyParams = {1, 16, 0, 0}。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="kt">uint64_t</span><span class="o">&gt;</span><span class="w"> </span><span class="n">quantAlphaTensor</span><span class="p">(</span><span class="n">AscendC</span><span class="o">::</span><span class="n">TPosition</span><span class="o">::</span><span class="n">C1</span><span class="p">,</span><span class="w"> </span><span class="n">c1Addr</span><span class="p">,</span><span class="w"> </span><span class="n">N</span><span class="p">);</span>

<span class="k">if</span><span class="w"> </span><span class="k">constexpr</span><span class="w"> </span><span class="p">(</span><span class="n">scenarioNum</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="mi">2</span><span class="w"> </span><span class="o">||</span><span class="w"> </span><span class="n">scenarioNum</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="mi">4</span><span class="w"> </span><span class="o">||</span><span class="w"> </span><span class="n">scenarioNum</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="mi">6</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">CopyQuantAlphaGmToL1</span><span class="p">(</span><span class="n">quantAlphaTensor</span><span class="p">);</span>
<span class="p">}</span>

<span class="c1">// vector quant mode</span>
<span class="k">if</span><span class="w"> </span><span class="k">constexpr</span><span class="w"> </span><span class="p">(</span><span class="n">scenarioNum</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="mi">2</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">intriParams</span><span class="p">.</span><span class="n">quantPre</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">QuantMode_t</span><span class="o">::</span><span class="n">VDEQF16</span><span class="p">;</span>
<span class="p">}</span><span class="w"> </span><span class="k">else</span><span class="w"> </span><span class="k">if</span><span class="w"> </span><span class="k">constexpr</span><span class="w"> </span><span class="p">(</span><span class="n">scenarioNum</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="mi">4</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">intriParams</span><span class="p">.</span><span class="n">quantPre</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">QuantMode_t</span><span class="o">::</span><span class="n">VQF322B8_PRE</span><span class="p">;</span>
<span class="p">}</span><span class="w"> </span><span class="k">else</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">intriParams</span><span class="p">.</span><span class="n">quantPre</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">QuantMode_t</span><span class="o">::</span><span class="n">VREQ8</span><span class="p">;</span>
<span class="p">}</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="kt">uint64_t</span><span class="o">&gt;</span><span class="w"> </span><span class="n">fbTensor</span><span class="p">(</span><span class="n">AscendC</span><span class="o">::</span><span class="n">TPosition</span><span class="o">::</span><span class="n">C2PIPE2GM</span><span class="p">,</span><span class="w"> </span><span class="n">fbAddr</span><span class="p">,</span><span class="w"> </span><span class="n">N</span><span class="p">);</span>
<span class="kt">uint16_t</span><span class="w"> </span><span class="n">burstLen</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">CeilAlign</span><span class="p">(</span><span class="n">n</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="kt">uint64_t</span><span class="p">),</span><span class="w"> </span><span class="mi">128</span><span class="p">)</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="mi">128</span><span class="p">;</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopyParams</span><span class="w"> </span><span class="nf">dataCopyParams</span><span class="p">(</span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="n">burstLen</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">fbTensor</span><span class="p">,</span><span class="w"> </span><span class="n">quantAlphaTensor</span><span class="p">,</span><span class="w"> </span><span class="n">dataCopyParams</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">SetFixPipeConfig</span><span class="p">(</span><span class="n">fbTensor</span><span class="p">);</span>
</code></pre></div><p>完整示例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_basic_api/00_data_movement/data_copy_l0c2gm">DataCopy（L1-&gt;Fixpipe Buffer数据搬运）</a>中场景2、4、6。</p></article></div>`,1)])])}const w=a(t,[["render",e]]);export{h as __pageData,w as default};
